window.SPRITE_PAL = { '1':[107,247,154], '2':[46,125,79], '3':[215,255,232], '4':[18,44,28] };

/* 用名字當種子，同一個人每次看到的組合都一樣（不會每次重整就換） */
window.spriteSeed = function(str){
  var h = 2166136261;
  for (var i = 0; i < str.length; i++){ h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
  return function(){ h ^= h << 13; h ^= h >>> 17; h ^= h << 5; return ((h >>> 0) % 10000) / 10000; };
};

/* 橫向重複的花邊 */
window.drawLace = function(canvas, motif, targetW){
  var m = LACE[motif] || LACE['菱形'];
  var th = m.length, tw = m[0].length;
  var reps = Math.max(1, Math.round((targetW || 120) / tw)), W = tw * reps;
  canvas.width = W; canvas.height = th;
  var ctx = canvas.getContext('2d'), img = ctx.createImageData(W, th);
  for (var y = 0; y < th; y++){
    for (var x = 0; x < W; x++){
      var ch = m[y][x % tw], i = (y * W + x) * 4;
      if (ch === '.' || ch === ' ') { img.data[i+3] = 0; continue; }
      var c = SPRITE_PAL[ch] || SPRITE_PAL['1'];
      img.data[i] = c[0]; img.data[i+1] = c[1]; img.data[i+2] = c[2]; img.data[i+3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
};

/* 把幾個 sprite 併排畫進一張 canvas */
window.drawSpriteRow = function(canvas, names, gap){
  gap = gap == null ? 6 : gap;
  var gs = names.map(function(n){ return SPRITES.scene[n] || SPRITES.big[n]; }).filter(Boolean);
  if (!gs.length) return;
  var ws = gs.map(function(g){ return Math.max.apply(null, g.map(function(r){ return r.length; })); });
  var hs = gs.map(function(g){ return g.length; });
  var W = ws.reduce(function(a,b){ return a+b; }, 0) + gap * (gs.length - 1);
  var H = Math.max.apply(null, hs);
  canvas.width = W; canvas.height = H;
  var ctx = canvas.getContext('2d'), img = ctx.createImageData(W, H);
  var ox = 0;
  gs.forEach(function(g, k){
    var oy = H - hs[k];                       // 底部對齊，像站在同一條地面上
    for (var y = 0; y < g.length; y++){
      for (var x = 0; x < g[y].length; x++){
        var ch = g[y][x];
        if (ch === '.' || ch === ' ') continue;
        var c = SPRITE_PAL[ch] || SPRITE_PAL['1'];
        var i = ((oy + y) * W + ox + x) * 4;
        img.data[i] = c[0]; img.data[i+1] = c[1]; img.data[i+2] = c[2]; img.data[i+3] = 255;
      }
    }
    ox += ws[k] + gap;
  });
  ctx.putImageData(img, 0, 0);
};
